import java.util.ArrayDeque;
import java.util.Deque;

class Solution {
    public TreeNode recoverFromPreorder(String traversal) {
        Deque<TreeNode> stack = new ArrayDeque<>();
        int index = 0;
        while (index < traversal.length()) {
            int depth = 0;
            while (index < traversal.length() && traversal.charAt(index) == '-') {
                depth++;
                index++;
            }

            int value = 0;
            while (index < traversal.length() && traversal.charAt(index) != '-') {
                value = value * 10 + traversal.charAt(index) - '0';
                index++;
            }

            TreeNode node = new TreeNode(value);
            while (stack.size() > depth) {
                stack.pop();
            }
            if (!stack.isEmpty()) {
                TreeNode parent = stack.peek();
                if (parent.left == null) {
                    parent.left = node;
                } else {
                    parent.right = node;
                }
            }
            stack.push(node);
        }

        while (stack.size() > 1) {
            stack.pop();
        }
        return stack.peek();
    }
}

class Solution {
    private int index;

    public TreeNode recoverFromPreorder(String traversal) {
        index = 0;
        return build(traversal, 0);
    }

    private TreeNode build(String traversal, int expectedDepth) {
        int scan = index;
        int depth = 0;
        while (scan < traversal.length() && traversal.charAt(scan) == '-') {
            depth++;
            scan++;
        }
        if (depth != expectedDepth) {
            return null;
        }

        int value = 0;
        index = scan;
        while (index < traversal.length() && traversal.charAt(index) != '-') {
            value = value * 10 + traversal.charAt(index) - '0';
            index++;
        }

        TreeNode node = new TreeNode(value);
        node.left = build(traversal, expectedDepth + 1);
        node.right = build(traversal, expectedDepth + 1);
        return node;
    }
}

class Solution {
    public TreeNode recoverFromPreorder(String traversal) {
        TreeNode[] lastAtDepth = new TreeNode[1001];
        TreeNode root = null;
        int index = 0;

        while (index < traversal.length()) {
            int depth = 0;
            while (index < traversal.length() && traversal.charAt(index) == '-') {
                depth++;
                index++;
            }

            int value = 0;
            while (index < traversal.length() && Character.isDigit(traversal.charAt(index))) {
                value = value * 10 + traversal.charAt(index) - '0';
                index++;
            }

            TreeNode node = new TreeNode(value);
            lastAtDepth[depth] = node;
            if (depth == 0) {
                root = node;
            } else {
                TreeNode parent = lastAtDepth[depth - 1];
                if (parent.left == null) {
                    parent.left = node;
                } else {
                    parent.right = node;
                }
            }
        }
        return root;
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.List;

class Solution {
    private static final class Token {
        final int depth;
        final int value;
        Token(int depth, int value) {
            this.depth = depth;
            this.value = value;
        }
    }

    public TreeNode recoverFromPreorder(String traversal) {
        List<Token> tokens = tokenize(traversal);
        Deque<TreeNode> stack = new ArrayDeque<>();
        TreeNode root = null;

        for (Token token : tokens) {
            TreeNode node = new TreeNode(token.value);
            while (stack.size() > token.depth) {
                stack.pop();
            }
            if (stack.isEmpty()) {
                root = node;
            } else if (stack.peek().left == null) {
                stack.peek().left = node;
            } else {
                stack.peek().right = node;
            }
            stack.push(node);
        }
        return root;
    }

    private List<Token> tokenize(String traversal) {
        List<Token> tokens = new ArrayList<>();
        int index = 0;
        while (index < traversal.length()) {
            int depth = 0;
            while (index < traversal.length() && traversal.charAt(index) == '-') {
                depth++;
                index++;
            }
            int value = 0;
            while (index < traversal.length() && Character.isDigit(traversal.charAt(index))) {
                value = value * 10 + traversal.charAt(index) - '0';
                index++;
            }
            tokens.add(new Token(depth, value));
        }
        return tokens;
    }
}

import java.util.ArrayList;
import java.util.List;

class Solution {
    private List<Integer> depths;
    private List<Integer> values;
    private int tokenIndex;

    public TreeNode recoverFromPreorder(String traversal) {
        depths = new ArrayList<>();
        values = new ArrayList<>();
        tokenize(traversal);
        tokenIndex = 0;
        return build(0);
    }

    private TreeNode build(int expectedDepth) {
        if (tokenIndex == values.size() || depths.get(tokenIndex) != expectedDepth) {
            return null;
        }
        TreeNode node = new TreeNode(values.get(tokenIndex));
        tokenIndex++;
        node.left = build(expectedDepth + 1);
        node.right = build(expectedDepth + 1);
        return node;
    }

    private void tokenize(String traversal) {
        int index = 0;
        while (index < traversal.length()) {
            int depth = 0;
            while (index < traversal.length() && traversal.charAt(index) == '-') {
                depth++;
                index++;
            }
            int value = 0;
            while (index < traversal.length() && Character.isDigit(traversal.charAt(index))) {
                value = value * 10 + traversal.charAt(index) - '0';
                index++;
            }
            depths.add(depth);
            values.add(value);
        }
    }
}
